94:     if (typeof value.format === 'function') {
95:       return value.format(options);
96:     }
97:     else if (value && value.toString() !== {}.toString()) {
98:       // this object has a non-native toString method, use that one
99:       return value.toString();
100:     }
101:     else {
102:       var entries = [];
103: 
104:       for (var key in value) {
105:         if (value.hasOwnProperty(key)) {
106:           entries.push('"' + key + '": ' + exports.format(value[key], options));
107:         }
108:       }
