134:  * @param {Array} array
135:  * @param {Object | number | Function} [options]  Formatting options. See
136:  *                                                lib/utils/number:format for a
137:  *                                                description of the available
138:  *                                                options.
139:  * @returns {string} str
140:  */
141: function formatArray (array, options) {
142:   if (Array.isArray(array)) {
143:     var str = '[';
144:     var len = array.length;
145:     for (var i = 0; i < len; i++) {
146:       if (i != 0) {
